"""Original visual, passage and dataset questions with explicit worked answers."""

def extend(topic, add, questions):
    diagram=topic('diagram-patterns','Logical','Diagram sequences and stated rules','Track shape, orientation, fill and count separately; apply the stated transformation.','A diagram can change along several independent dimensions. Describe the rule for each, then verify every shown step.','Annotate the direction or count beneath each figure before choosing.','Do not assume a rotation is a reflection or invent an unstated extra rule.')
    reading=topic('reading-evidence','Verbal','Passage evidence and inference','Separate stated facts, supported inferences and claims beyond the passage.','Use the exact scope, qualifiers and evidence in the passage. A plausible outside fact is not a supported answer.','Reject choices that reverse, exaggerate or introduce a new claim.','Association alone does not establish causation; a partial result is not a universal guarantee.')
    chart=topic('chart-caselets','DataInterpretation','Charts, tables and weighted comparisons','Change % = (new-old)/old x 100; share % = part/total x 100; weighted mean = sum(value x weight)/sum(weight).','Read units, categories and denominator first. Compute totals explicitly and distinguish counts, shares and growth.','Estimate the expected range, then calculate with the correct base.','Do not average percentages from unequal groups or divide growth by the new value.')
    def q(key,prompt,correct,wrong,explanation,visual=None,passage=None,rule=None):
        add(key,prompt,correct,explanation,distractors=wrong)
        item=questions[-1]
        if visual:item['visual']=visual
        if passage:item['passage']=passage
        if rule:item['formula']=rule
        item['origin']='StudyLab original visual/passage/caselet practice'
    def sequence(title,items,alt):return dict(type='sequence',title=title,items=items,alt=alt)
    def arrows(angles):return [dict(shape='arrow',angle=a) for a in angles]+[dict(shape='missing')]
    def shapes(names):return [dict(shape=s) for s in names]+[dict(shape='missing')]
    def dots(counts):return [dict(shape='dots',count=n) for n in counts]+[dict(shape='missing')]
    q(diagram,'D1: The arrow turns 90 degrees clockwise at every step. Which direction replaces the question mark?','Right',['Up','Down','Left'],'Right becomes Down, then Left, then Up. Another 90-degree clockwise turn returns to Right.',sequence('Clockwise quarter turns',arrows([0,90,180,270]),'Right, Down, Left, Up, missing.'))
    q(diagram,'D2: The arrow turns 90 degrees anticlockwise at every step. What comes after the last shown arrow?','Down',['Right','Up','Left'],'The orientations are Down, Right, Up, Left. The next anticlockwise quarter turn from Left is Down.',sequence('Anticlockwise quarter turns',arrows([90,0,270,180]),'Down, Right, Up, Left, missing.'))
    q(diagram,'D3: The shape cycle is circle, square, repeated. Which shape is missing?','Circle',['Square','Triangle','No shape'],'The repeating two-shape cycle is circle/square. Four shown positions complete two cycles, so the fifth begins with a circle.',sequence('Two-shape cycle',shapes(['circle','square','circle','square']),'Circle, square, circle, square, missing.'))
    q(diagram,'D4: Repeat circle, triangle, square in that order. Which shape follows the fifth shown figure?','Square',['Circle','Triangle','A pair of circles'],'The positions are circle, triangle, square, circle, triangle. The sixth completes the second cycle with square.',sequence('Three-shape cycle',shapes(['circle','triangle','square','circle','triangle']),'Circle, triangle, square, circle, triangle, missing.'))
    q(diagram,'D5: The number of dots increases by two each time. How many dots belong in the missing figure?','9',['8','10','7'],'The counts are 1, 3, 5 and 7. Adding two to 7 gives 9; count dots rather than rows.',sequence('Dot-count increase',dots([1,3,5,7]),'1 dot, 3 dots, 5 dots, 7 dots, missing.'))
    q(diagram,'D6: Each next figure removes one dot. What is the missing dot count?','2',['1','3','4'],'The counts are 6, 5, 4, 3. The same decrement gives 2 next.',sequence('Dot-count decrease',dots([6,5,4,3]),'6 dots, 5 dots, 4 dots, 3 dots, missing.'))
    q(diagram,'D7: Shape stays circular while fill alternates outline, filled. Which figure is missing?','Outline circle',['Filled circle','Outline square','Filled triangle'],'The four circles are outline, filled, outline, filled. Position five is an outline circle; the shape does not change.',sequence('Alternating fill',[dict(shape='circle',filled=f) for f in [False,True,False,True]]+[dict(shape='missing')],'Outline circle, filled circle, outline circle, filled circle, missing.'))
    q(diagram,'D8: Shapes repeat triangle, square, circle, and fill alternates outline, filled. Which completes the sixth position?','Filled circle',['Outline circle','Filled square','Outline triangle'],'Position six in the three-shape cycle is circle. Even positions are filled, so the missing figure is a filled circle.',sequence('Shape and fill together',[dict(shape=s,filled=f) for s,f in [('triangle',False),('square',True),('circle',False),('triangle',True),('square',False)]]+[dict(shape='missing')],'Outline triangle, filled square, outline circle, filled triangle, outline square, missing.'))
    q(diagram,'D9: Each direction appears twice before a 90-degree clockwise turn. Which direction comes next?','Up',['Right','Down','Left'],'The pairs are Right/Right, Down/Down, Left/Left. The next pair begins Up after a clockwise turn from Left.',sequence('Paired directions',arrows([0,0,90,90,180,180]),'Right, Right, Down, Down, Left, Left, missing.'))
    q(diagram,'D10: The arrow reverses by 180 degrees at every step. What replaces the missing figure?','Right',['Up','Down','Left'],'Right reverses to Left and then to Right. The alternating sequence Right, Left, Right, Left continues with Right.',sequence('Half-turn pattern',arrows([0,180,0,180]),'Right, Left, Right, Left, missing.'))
    q(diagram,'D11: The cycle is two circles followed by one triangle. Which shape replaces the question mark?','Triangle',['Circle','Square','No shape'],'Circle/circle/triangle repeats. The fourth and fifth are circles, so the sixth is triangle.',sequence('Grouped shape cycle',shapes(['circle','circle','triangle','circle','circle']),'Circle, circle, triangle, circle, circle, missing.'))
    q(diagram,'D12: Remove two dots at each step. How many dots complete the sequence?','2',['0','3','6'],'The counts 8, 6, 4 decrease by two; the next is 2.',sequence('Even-count decrease',dots([8,6,4]),'8 dots, 6 dots, 4 dots, missing.'))

    p1='A study club compared its members\' revision logs over six weeks. Members who used short sessions spread across several days remembered more of the material on a later quiz than members who concentrated their study into one evening. The club did not assign schedules randomly: members chose when and how to study. Several other differences, including prior familiarity and total practice time, were not controlled. The organisers therefore recommended trying spaced sessions and measuring personal results, while cautioning that their logs alone did not prove which factor caused the score difference.'
    q(reading,'Passage A: Which conclusion best matches the organisers\' evidence?','Spaced sessions were associated with higher later scores in these logs.',['Spaced sessions were proved to cause every score difference.','One evening of study can never help anyone.','The club randomly assigned every member a schedule.'],'The passage reports an observed association and explicitly says schedules were self-selected and other factors uncontrolled.',passage=p1)
    q(reading,'Passage A: Why could the logs not establish causation by themselves?','Schedules were self-selected and other relevant differences were uncontrolled.',['No later quiz was given.','Every member studied the same total time by design.','The organisers measured only the colour of notebooks.'],'The stated limitations are nonrandom schedule choice plus uncontrolled familiarity/practice time, which allow alternative explanations.',passage=p1)
    q(reading,'Passage A: What action did the organisers actually recommend?','Try spaced sessions and measure personal results.',['Stop all revision immediately.','Guarantee a perfect score after one week.','Remove the later quiz from the comparison.'],'The recommendation is a measured personal trial, not a universal score guarantee or a claim that one factor is proven.',passage=p1)
    p2='A library app saves a reader\'s notes immediately in that browser. Its optional local launcher also writes a private backup in the app folder. The status label distinguishes these two events because a browser save can succeed while the folder server is unavailable. Opening the public website on another device does not automatically retrieve the folder backup. To move work, readers export a progress file and import it in the other edition. The import preserves unrelated saved items but replaces matching entries from the file. The guide asks readers to export current work before replacing a conflicting entry.'
    q(reading,'Passage B: What does a successful browser save guarantee in this description?','The note was saved in that browser; folder backup may still be pending.',['Every device has received the note.','The public website has uploaded the private folder automatically.','A missing folder server has become available.'],'The status distinction exists precisely because browser persistence and folder acknowledgement are separate events.',passage=p2)
    q(reading,'Passage B: How does the described app transfer progress between separate editions?','Export a progress file and import it in the other edition.',['Assume the same filename creates cloud sync.','Clear every browser\'s storage first.','Rename a note and wait for an unspecified service.'],'The passage explicitly gives export/import as the transfer method and denies automatic retrieval on another device.',passage=p2)
    q(reading,'Passage B: Why export current work before importing a conflicting entry?','Matching saved entries can be replaced by the imported file.',['The app cannot read any JSON.','Unrelated items are always deleted.','Every imported file is automatically public.'],'The passage distinguishes preserved unrelated items from replaced matching ones, making a current backup useful before replacement.',passage=p2)
    p3='During a ten-week water-saving trial, a town installed soil sensors in three parks and watered only when readings passed a chosen threshold. Water use fell compared with the same parks\' previous ten weeks, while the recorded plant-health score stayed within the maintenance team\'s acceptable range. Rainfall was also higher during the trial. The report called the approach promising but requested another comparison across a drier period before recommending a town-wide rollout. It did not claim that the sensors alone explained all the reduction.'
    q(reading,'Passage C: Which factor complicates attributing the entire water reduction to sensors?','Rainfall was higher during the trial.',['The parks had no plants.','The trial lasted exactly one hour.','The maintenance team recorded no health information.'],'Higher rainfall could reduce watering needs independently of the sensors, so it is an alternative contributing factor.',passage=p3)
    q(reading,'Passage C: In context, promising most nearly means what?','Encouraging enough to investigate further.',['Already proved perfect in every season.','Certain to fail immediately.','Unrelated to the trial results.'],'The report pairs promising with a request for further testing, so it signals encouragement without certainty.',passage=p3)
    q(reading,'Passage C: What did the report request before a town-wide rollout?','Another comparison across a drier period.',['An immediate guarantee that rainfall never matters.','Removal of every plant-health check.','A conclusion that all savings came from sensors.'],'The requested next evidence is a drier-period comparison; the report explicitly avoids a complete causal claim.',passage=p3)
    p4='A small shop reduced the price of one notebook range and sold more units the next month. Its sales dashboard highlighted the higher unit count, but the owner asked for purchase costs, discounts and delivery charges before deciding whether the promotion had improved profit. Some customers also bought other products during the visit, and the shop had not yet separated those additional sales from ordinary monthly demand. The owner described the promotion as worth analysing, rather than declaring it either a success or a failure from the unit count alone.'
    q(reading,'Passage D: Why did the owner request more information?','More units sold does not by itself establish higher profit.',['Unit counts always equal profit.','Purchase costs can never affect profit.','Every extra sale was already proved to come from the promotion.'],'Profit depends on relevant revenue and costs; the passage also leaves the source of additional sales unresolved.',passage=p4)
    q(reading,'Passage D: Which statement goes beyond the passage?','Every additional sale was caused by the notebook promotion.',['The notebook range sold more units.','The owner asked about costs and charges.','Additional sales were not yet separated from ordinary demand.'],'The passage explicitly says additional sales had not been separated from ordinary demand, so universal causal attribution is unsupported.',passage=p4)
    q(reading,'Passage D: Which phrase best describes the owner\'s approach?','Evaluate the relevant evidence before judging the promotion.',['Judge profit from unit count alone.','Ignore all costs permanently.','Declare failure without analysis.'],'The owner asks for the missing cost/context evidence and avoids both premature success and premature failure claims.',passage=p4)

    a=dict(type='bar',title='Library books issued by day (books)',labels=['Mon','Tue','Wed','Thu','Fri'],values=[80,100,60,120,140])
    q(chart,'Books chart: What is the percentage increase from Monday to Friday?','75%',['42.86%','60%','175%'],'The increase is 140-80=60 books. Divide by Monday\'s base 80: 60/80 x 100=75%.',visual=a,rule='Growth % = (new-old)/old x 100.')
    q(chart,'Books chart: Thursday accounts for what percentage of all books issued over these five days?','24%',['20%','30%','12%'],'The total is 80+100+60+120+140=500. Thursday\'s share is 120/500 x 100=24%.',visual=a,rule='Share % = category count / total count x 100.')
    b=dict(type='bar',title='Practice questions completed by section (questions)',labels=['Quant','Logic','Verbal','Code'],values=[24,18,30,12])
    q(chart,'Section chart: Quant and Logic together are what percentage of all completed questions?','50%',['42%','60%','25%'],'Quant plus Logic is 24+18=42. The total is 84, so 42/84 x 100=50%.',visual=b)
    q(chart,'Section chart: How many more Verbal questions than Coding questions were completed?','18',['12','30','42'],'Verbal is 30 and Coding is 12. The absolute difference is 30-12=18 questions.',visual=b,rule='Absolute difference = larger count - smaller count.')
    d=dict(type='bar',title='Units shipped by branch',labels=['A','B','C','D'],values=[120,160,80,140])
    q(chart,'Branches chart: What percentage of all units came from branch B?','32%',['40%','25%','28%'],'Total units are 120+160+80+140=500. Branch B contributes 160/500 x 100=32%.',visual=d)
    q(chart,'Branches chart: What is the mean number of units shipped per branch?','125',['120','140','160'],'The four branches shipped 500 units in total. The mean is 500/4=125 units.',visual=d,rule='Arithmetic mean = total / number of equally weighted groups.')
    e=dict(type='bar',title='Production by year (thousand units)',labels=['2023','2024','2025'],values=[240,300,360])
    q(chart,'Production chart: What is the total percentage growth from 2023 to 2025?','50%',['33.33%','20%','120%'],'The increase is 360-240=120 thousand units. Relative to the 2023 base, 120/240 x 100=50%.',visual=e)
    q(chart,'Production chart: What is the percentage growth from 2024 to 2025?','20%',['25%','16.67%','60%'],'The increase is 60 thousand units from a base of 300. Thus 60/300 x 100=20%.',visual=e)
    f=dict(type='table',title='Applications and selections (candidates)',columns=['Department','Applied','Selected'],rows=[['Engineering',240,60],['Commerce',180,36],['Arts',160,40]])
    q(chart,'Selection table: Which departments tie for the highest selection rate?','Engineering and Arts',['Engineering and Commerce','Commerce and Arts','All three departments'],'Engineering: 60/240=25%; Commerce:36/180=20%; Arts:40/160=25%. Engineering and Arts tie at 25%.',visual=f,rule='Selection rate = selected / applied x 100.')
    q(chart,'Selection table: How many applicants in total were not selected?','444',['136','396','480'],'Applied total=240+180+160=580. Selected total=60+36+40=136. Not selected=580-136=444.',visual=f,rule='Not selected = total applied - total selected.')
    g=dict(type='table',title='Items sold, with price per unit (INR)',columns=['Item','Quantity','Unit price'],rows=[['Pens',30,10],['Notebooks',20,40],['Files',10,25]])
    q(chart,'Sales table: To two decimal places, what percentage of revenue came from notebooks?','59.26%',['44.44%','62.50%','50.00%'],'Revenue is 30x10+20x40+10x25=1350. Notebooks give 800. The share is 800/1350 x 100=59.259..., rounded to 59.26%.',visual=g,rule='Revenue share % = item quantity x unit price / total revenue x 100.')
    q(chart,'Sales table: What is the quantity-weighted mean selling price per unit?','INR 22.50',['INR 25.00','INR 30.00','INR 20.00'],'Total revenue is INR 1350 and total units are 30+20+10=60. Weighted mean=1350/60=INR 22.50, not the unweighted mean of three prices.',visual=g,rule='Weighted mean price = total revenue / total units.')
